query:
UPDATE molecules SET therapeutic_properties = 'Anxiolytique, sédatif, anti-inflammatoire, analgésique, antimicrobien. Études cliniques: réduction de l''anxiété (Linck et al., 2010), effet sédatif (Buchbauer et al., 1991).' WHERE id = 30009;

UPDATE molecules SET therapeutic_properties = 'Antimicrobien puissant, antifongique, anti-inflammatoire, antioxydant. Études: activité contre Candida albicans, effet anti-inflammatoire via inhibition COX-2.' WHERE id IN (570041, 810023);

UPDATE molecules SET therapeutic_properties = 'Antiseptique, antifongique, antibactérien, antioxydant, anti-inflammatoire. Utilisé en médecine traditionnelle pour infections respiratoires et digestives.' WHERE id IN (570042, 810024);

UPDATE molecules SET therapeutic_properties = 'Antimicrobien, antifongique, insectifuge naturel. Études: activité contre dermatophytes, effet répulsif contre moustiques (Aedes aegypti).' WHERE id = 570045;

UPDATE molecules SET therapeutic_properties = 'Analgésique topique (activation TRPM8), décongestionnant nasal, antispasmodique, antimicrobien. Utilisé pour douleurs musculaires, maux de tête, troubles digestifs.' WHERE id = 570046;

UPDATE molecules SET therapeutic_properties = 'Expectorant, mucolytique, anti-inflammatoire, antimicrobien, analgésique. Utilisé pour infections respiratoires, sinusite, bronchite. Études: effet anti-inflammatoire via inhibition cytokines.' WHERE id = 570048;

UPDATE molecules SET therapeutic_properties = 'Anti-inflammatoire, cicatrisant, antimicrobien, apaisant cutané. Composant majeur de la camomille allemande. Études: inhibition de la 5-lipoxygénase, cicatrisation accélérée.' WHERE id = 720016;

UPDATE molecules SET therapeutic_properties = 'Antimicrobien, insectifuge, anti-inflammatoire, cicatrisant. Études: activité contre bactéries Gram+, effet répulsif contre insectes.' WHERE id IN (660002, 330007);

UPDATE molecules SET therapeutic_properties = 'Antimicrobien, antioxydant, anti-inflammatoire, insectifuge. Études: activité contre Staphylococcus aureus, effet répulsif contre moustiques.' WHERE id IN (810042);

UPDATE molecules SET therapeutic_properties = 'Antimicrobien, anti-inflammatoire, antioxydant, insectifuge naturel. Études: activité contre dermatophytes, effet répulsif contre tiques.' WHERE id = 810043;

UPDATE molecules SET therapeutic_properties = 'Analgésique, anti-inflammatoire, bronchodilatateur. Études: effet analgésique via récepteurs TRPV3, activité anti-inflammatoire via inhibition NF-κB.' WHERE id = 900007;

UPDATE molecules SET therapeutic_properties = 'Bronchodilatateur, anti-inflammatoire, antimicrobien, insectifuge. Études: effet bronchodilatateur via récepteurs β2-adrénergiques, activité contre Streptococcus pneumoniae.' WHERE id = 900008;

UPDATE molecules SET therapeutic_properties = 'Anti-inflammatoire, analgésique, anxiolytique, gastroprotecteur. Agoniste CB2 (cannabinoïde). Études: réduction inflammation via inhibition COX-2 et prostaglandines.' WHERE id = 900009;

UPDATE molecules SET therapeutic_properties = 'Analgésique topique, anti-inflammatoire, antimicrobien, insectifuge. Utilisé traditionnellement pour douleurs musculaires et articulaires. Études: effet analgésique via récepteurs TRPV1.' WHERE id = 960003;

UPDATE molecules SET therapeutic_properties = 'Analgésique, anti-inflammatoire, antimicrobien, sédatif léger. Utilisé en médecine traditionnelle chinoise. Études: effet analgésique comparable à l''aspirine.' WHERE id = 990002;

